// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }

    function testFuzz_property(uint256 amount, bool willRevert) public {
        amount = bound(amount, 1, 1 ether);

        BadRecipient bad = new BadRecipient(willRevert);

        address actor = address(0xABCD);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        assertEq(address(c).balance, amount);

        vm.deal(address(bad), amount);
        vm.prank(address(bad));
        c.deposit{value: amount}();
        assertEq(address(c).balance, amount * 2);

        uint256 before = address(c).balance;

        vm.prank(address(bad));
        bool ok;
        try c.withdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(address(c).balance == before - amount);
        } else {
            assertTrue(address(c).balance == before);
        }
    }
}

contract BadRecipient {
    bool public willRevert;
    constructor(bool _willRevert) {
        willRevert = _willRevert;
    }
    receive() external payable {
        if (willRevert) revert("bad recipient");
    }
}
